sp_widget.client_script:
function widgetcontroller($scope, $timeout, $rootScope, $document, $window) {
  var c = this;
  c.loading = false;
  c.tableSearch = '';
  c.filteredList = [];
  c.limit = 15;
  c.page = 0;

  c.counts = { total: 0, overdue: 0, review15: 0, review30: 0, highRisk: 0, pending: 0, sendBack: 0, rejected: 0, expiring: 0 };

  c.filters = {
      businessType: 'all', // 'all', 'T00' (Trade), or 'N01' (Non-Trade)
      regions: [],
      depots: [],
      segment: '',
      period: 'latest'
  };

  function handleClickOutside(event) {
    var target = event.target;
    if (target.closest('.clm-multiselect-container')) return;
    $timeout(function() {
      c.regionDropdownOpen = false;
      c.depotDropdownOpen = false;
    });
  }
  $document.on('click', handleClickOutside);
  $scope.$on('$destroy', function() { $document.off('click', handleClickOutside); });

  // ---- Region Multiselect ----
  c.regionDropdownOpen = false;
  c.regionSearch = '';
  c.selectedRegionLabels = [];
  c.openRegionDropdown = function() { c.regionDropdownOpen = true; c.depotDropdownOpen = false; };
  c.closeRegionDropdown = function() { $timeout(function() { c.regionDropdownOpen = false; }, 200); };

  c.toggleRegion = function(r) {
      var idx = c.filters.regions.indexOf(r.value);
      if (idx === -1) { 
          c.filters.regions.push(r.value); 
          c.selectedRegionLabels.push(r.label); 
      } else { 
          c.filters.regions.splice(idx, 1); 
          c.selectedRegionLabels.splice(idx, 1); 
      }
      c.filters.depots = []; c.selectedDepotLabels = []; c.regionSearch = ''; c.refresh();
  };

  c.selectAllRegions = function() {
      var allRegions = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      c.filters.regions = allRegions.map(function(r) { return r.value; });
      c.selectedRegionLabels = allRegions.map(function(r) { return r.label; });
      c.filters.depots = []; c.selectedDepotLabels = []; c.regionSearch = ''; c.refresh();
  };

  c.clearAllRegions = function() {
      c.filters.regions = []; c.selectedRegionLabels = []; 
      c.filters.depots = []; c.selectedDepotLabels = [];
      c.regionSearch = ''; c.refresh();
  };

  c.isRegionSelected = function(r) { return c.filters.regions.indexOf(r.value) !== -1; };
  c.getFilteredRegions = function() {
      var all = c.data.filterOpts.regions || [];
      var term = (c.regionSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(r) { return String(r.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getRegionDisplayText = function() {
      if (!c.selectedRegionLabels || c.selectedRegionLabels.length === 0) return 'All Regions';
      if (c.selectedRegionLabels.length === 1) return c.selectedRegionLabels[0];
      return c.selectedRegionLabels.length + ' regions selected';
  };

  // ---- Depot Multiselect ----
  c.depotDropdownOpen = false;
  c.depotSearch = '';
  c.selectedDepotLabels = [];
  c.openDepotDropdown = function() { c.depotDropdownOpen = true; c.regionDropdownOpen = false; };
  c.closeDepotDropdown = function() { $timeout(function() { c.depotDropdownOpen = false; }, 200); };

  c.toggleDepot = function(d) {
      var idx = c.filters.depots.indexOf(d.value);
      if (idx === -1) { 
          c.filters.depots.push(d.value); 
          c.selectedDepotLabels.push(d.label); 
      } else { 
          c.filters.depots.splice(idx, 1); 
          c.selectedDepotLabels.splice(idx, 1); 
      }
      c.depotSearch = ''; c.refresh();
  };

  c.selectAllDepots = function() {
      var allDepots = (c.data && c.data.filterOpts && c.data.filterOpts.depots) || [];
      c.filters.depots = allDepots.map(function(d) { return d.value; });
      c.selectedDepotLabels = allDepots.map(function(d) { return d.label; });
      c.depotSearch = ''; c.refresh();
  };

  c.clearAllDepots = function() { 
      c.filters.depots = []; c.selectedDepotLabels = []; 
      c.depotSearch = ''; c.refresh(); 
  };
  c.isDepotSelected = function(d) { return c.filters.depots.indexOf(d.value) !== -1; };
  c.getFilteredDepots = function() {
      var all = c.data.filterOpts.depots || [];
      var term = (c.depotSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(d) { return String(d.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getDepotDisplayText = function() {
      if (!c.selectedDepotLabels || c.selectedDepotLabels.length === 0) return 'All Depots';
      if (c.selectedDepotLabels.length === 1) return c.selectedDepotLabels[0];
      return c.selectedDepotLabels.length + ' depots selected';
  };

  c.quickFilter = 'all';
  c.riskFilter = '';
  c.kpiFilter = '';

  c.setQuickFilter = function(f) { 
      c.quickFilter = f; 
      c.page = 0; 
      c.applyLocalFilters();
  };

  c.setKpiFilter = function(filterName) {
      c.kpiFilter = (c.kpiFilter === filterName) ? '' : filterName;
      c.page = 0;
      c.applyLocalFilters();
      $timeout(function() {
          var el = document.getElementById('clmTableContainer');
          if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
      }, 100);
  };

  c.setRiskKpiFilter = function() {
      c.riskFilter = (c.riskFilter === 'High') ? '' : 'High';
      c.page = 0;
      c.applyLocalFilters();
      $timeout(function() {
          var el = document.getElementById('clmTableContainer');
          if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
      }, 100);
  };

  c.isOverdue = function(row) {
      var val = (row.overdueTotal !== undefined && row.overdueTotal !== null) ? row.overdueTotal : (row.od90 || 0);
      return !!val && Number(val) > 0;
  };
  c.getReviewDays = function(row) {
      var parsed = parseInt(row.reviewIn, 10);
      return isNaN(parsed) ? null : parsed;
  };
  c.isReviewWithin = function(row, days) {
      var d = c.getReviewDays(row);
      return d !== null && d >= 0 && d <= days;
  };

  c.getActiveFilterCount = function() {
      var cnt = 0;
      if (c.filters.businessType && c.filters.businessType !== 'all') cnt++;
      if (c.filters.regions && c.filters.regions.length > 0) cnt++;
      if (c.filters.depots && c.filters.depots.length > 0) cnt++;
      if (c.filters.period && c.filters.period !== 'latest') cnt++;
      if (c.kpiFilter) cnt++;
      if (c.riskFilter) cnt++;
      if (c.quickFilter !== 'all') cnt++;
      if (c.tableSearch) cnt++;
      return cnt;
  };

  c.clearAllFilters = function() {
      c.filters.businessType = 'all';
      c.filters.regions = []; c.selectedRegionLabels = [];
      c.filters.depots = []; c.selectedDepotLabels = [];
      c.filters.period = 'latest';
      c.kpiFilter = ''; c.riskFilter = ''; c.quickFilter = 'all'; c.tableSearch = '';
      c.page = 0;
      c.refresh();
  };

  /* ===================== FAST LOCAL FILTERING ===================== */
  c.applyLocalFilters = function() {
      var rows = c.data.tableData || [];

      if (c.kpiFilter) {
          rows = rows.filter(function(row) {
              var s = (row.stateRaw || row.status || '').toLowerCase();
              if (c.kpiFilter === 'Pending' && s.indexOf('pend') === -1 && s.indexOf('submit') === -1 && s.indexOf('request') === -1) return false;
              if (c.kpiFilter === 'Send-back' && s.indexOf('send') === -1 && s.indexOf('back') === -1 && s.indexOf('return') === -1) return false;
              if (c.kpiFilter === 'Rejected' && s.indexOf('reject') === -1) return false;
              return true;
          });
      }

      if (c.riskFilter) {
          rows = rows.filter(function(row) { return row.risk === c.riskFilter; });
      }

      var q = (c.tableSearch || '').toLowerCase().trim();
      if (q) {
          rows = rows.filter(function(row) {
              return (row.code || '').toLowerCase().indexOf(q) > -1 ||
                     (row.name || '').toLowerCase().indexOf(q) > -1 ||
                     (row.pan  || '').toLowerCase().indexOf(q) > -1 ||
                     (row.region || '').toLowerCase().indexOf(q) > -1 ||
                     (row.depot  || '').toLowerCase().indexOf(q) > -1;
          });
      }

      if (c.quickFilter === 'overdue') rows = rows.filter(c.isOverdue);
      else if (c.quickFilter === 'review15') rows = rows.filter(function(row) { return c.isReviewWithin(row, 15); });
      else if (c.quickFilter === 'review30') rows = rows.filter(function(row) { return c.isReviewWithin(row, 30); });

      rows.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });

      c.filteredList = rows;
      c.updatePagination();
  };

  /* ===================== CACHED COUNTS ===================== */
  function updateCounts() {
      var base = c.data.tableData || [];
      c.counts.total = base.length;
      c.counts.overdue = 0; c.counts.review15 = 0; c.counts.review30 = 0; 
      c.counts.highRisk = 0; c.counts.pending = 0; c.counts.sendBack = 0; c.counts.rejected = 0; c.counts.expiring = 0;

      for (var i = 0; i < base.length; i++) {
          var r = base[i];
          if (c.isOverdue(r)) c.counts.overdue++;
          if (c.isReviewWithin(r, 15)) c.counts.review15++;
          if (c.isReviewWithin(r, 30)) c.counts.review30++;
          if (r.risk === 'High') c.counts.highRisk++;

          var s = (r.stateRaw || r.status || '').toLowerCase();
          if (s.indexOf('pend') > -1 || s.indexOf('submit') > -1 || s.indexOf('request') > -1) c.counts.pending++;
          if (s.indexOf('send') > -1 || s.indexOf('back') > -1 || s.indexOf('return') > -1) c.counts.sendBack++;
          if (s.indexOf('reject') > -1) c.counts.rejected++;

          if (r.reviewIn && parseInt(r.reviewIn) <= 15) c.counts.expiring++;
      }
  }

  // ---- SVG Outstanding Line Chart ----
  c.trendChart = { points: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };

  c.buildTrendChart = function() {
      var trend = (c.data && c.data.trend && c.data.trend.points) || [];
      if (!trend.length) { c.trendChart.points = []; return; }

      var width = 1200, height = 260, padLeft = 90, padRight = 60, padY = 25, padBottom = 35;
      var drawHeight = height - padY - padBottom;
      var baselineY = padY + drawHeight;

      var values = trend.map(function(p) { return p.value || 0; });
      var maxVal = Math.max.apply(null, values.concat([0]));
      if (maxVal <= 0) maxVal = 1;
      maxVal = maxVal * 1.1;

      var n = trend.length;
      var stepX = (width - padLeft - padRight) / Math.max(1, n - 1);
      var pts = trend.map(function(p, i) {
          var plotValue = Math.max(0, p.value || 0);
          var x = padLeft + i * stepX;
          var y = padY + (1 - plotValue / maxVal) * drawHeight;
          return { x: x, y: y, label: p.label, value: p.value || 0 };
      });

      var yTicks = [];
      for (var j = 0; j < 4; j++) {
          var tickVal = maxVal * (j / 3);
          var tickY = padY + (1 - tickVal / maxVal) * drawHeight;
          yTicks.push({ y: tickY, label: c.fmtCurrency(tickVal) });
      }
      var linePoints = pts.map(function(p) { return p.x + ',' + p.y; }).join(' ');
      var areaPath = 'M ' + pts[0].x + ',' + baselineY + ' ';
      pts.forEach(function(p) { areaPath += 'L ' + p.x + ',' + p.y + ' '; });
      areaPath += 'L ' + pts[pts.length - 1].x + ',' + baselineY + ' Z';

      c.trendChart = {
          points: pts, activePoints: pts, yTicks: yTicks, linePoints: linePoints, areaPath: areaPath,
          width: width, height: height, padLeft: padLeft, padRight: padRight,
          padY: padY, drawHeight: drawHeight, baselineY: baselineY
      };
  };

  /* ===================== CHART.JS SETUP ===================== */
  var CHART_JS_URL = 'https://cdn.jsdelivr.net/npm/chart.js@2.9.4/dist/Chart.min.js'; 

  function ensureChartJs(cb) {
      if (typeof Chart !== 'undefined') { cb(); return; }
      if (!window.__clmChartJsPromise) {
          window.__clmChartJsPromise = new Promise(function(resolve, reject) {
              var existing = document.querySelector('script[data-clm-chartjs]');
              if (existing) {
                  existing.addEventListener('load', resolve);
                  existing.addEventListener('error', reject);
                  return;
              }
              var script = document.createElement('script');
              script.src = CHART_JS_URL;
              script.setAttribute('data-clm-chartjs', 'true');
              script.onload = resolve;
              script.onerror = reject;
              document.head.appendChild(script);
          });
      }
      window.__clmChartJsPromise.then(function() { $timeout(cb); }).catch(function(err) { console.error('CLM Widget: failed to load Chart.js', err); });
  }

  var AGEING_COLORS = [
    { key: '0-30 Days',    color: '#38a169' },
    { key: '31-60 Days',   color: '#f6e05e' },
    { key: '61-90 Days',   color: '#f6ad55' },
    { key: '91-120 Days',  color: '#ed7d31' },
    { key: '121-180 Days', color: '#dd6b20' },
    { key: '>180 Days',    color: '#e53e3e' }
  ];

  var salesChartInstance = null;
  var ageingChartInstance = null;
  c.ageingLegend = [];

  c.renderCharts = function() {
    ensureChartJs(function() { renderSalesChart(); renderAgeingChart(); });
  };

  function renderSalesChart() {
      var canvas = document.getElementById('portfolioSalesChart');
      if (!canvas || !c.data.salesTrend || !c.data.salesTrend.points || !c.data.salesTrend.points.length) return;

      var labels = c.data.salesTrend.points.map(function(p) { return p.label || ''; });
      var volumes = c.data.salesTrend.points.map(function(p) { return p.volume || 0; });
      var values  = c.data.salesTrend.points.map(function(p) { return p.value || 0; });

      if (salesChartInstance) { try { salesChartInstance.destroy(); } catch(e) {} }

      salesChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar',
          data: {
              labels: labels,
              datasets: [
                  { type: 'line', label: 'Credit Sales Value (₹)', data: values, borderColor: '#ed7d31', backgroundColor: '#ed7d31', pointBackgroundColor: '#fff', pointBorderColor: '#ed7d31', pointBorderWidth: 2, pointRadius: 5, borderWidth: 3, lineTension: 0, fill: false, yAxisID: 'yValue' },
                  { type: 'bar', label: 'Credit Sales Volume (MT)', data: volumes, backgroundColor: '#4472c4', yAxisID: 'yVolume' }
              ]
          },
          options: {
              responsive: true, maintainAspectRatio: false, legend: { display: false }, 
              scales: {
                  xAxes: [{ gridLines: { display: false }, ticks: { fontSize: 11, fontColor: '#64748b' } }],
                  yAxes: [
                      { id: 'yVolume', type: 'linear', position: 'left', scaleLabel: { display: true, labelString: 'Credit Sales Volume (MT)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { color: '#e2e8f0' } },
                      { id: 'yValue', type: 'linear', position: 'right', scaleLabel: { display: true, labelString: 'Credit Sales Value (₹)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { drawOnChartArea: false } }
                  ]
              }
          }
      });
  }

  function renderAgeingChart() {
      var canvas = document.getElementById('portfolioAgeingChart');
      if (!canvas || !c.data.ageingTrend || !c.data.ageingTrend.months || !c.data.ageingTrend.months.length) return;

      var months = c.data.ageingTrend.months;
      var labels = months.map(function(m) { return m.label || ''; });

      var datasets = AGEING_COLORS.map(function(bucketDef) {
          return {
              label: bucketDef.key,
              backgroundColor: bucketDef.color,
              data: months.map(function(m) {
                  var match = m.buckets.filter(function(b) { return b.label === bucketDef.key; })[0];
                  return match ? (match.value || 0) : 0;
              })
          };
      });

      c.ageingLegend = AGEING_COLORS.map(function(b) { return { label: b.key, color: b.color }; });

      if (ageingChartInstance) { try { ageingChartInstance.destroy(); } catch(e) {} }

      ageingChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar', data: { labels: labels, datasets: datasets },
          options: {
              responsive: true, maintainAspectRatio: false, legend: { display: false }, 
              scales: {
                  xAxes: [{ stacked: true, gridLines: { display: false }, ticks: { fontSize: 11, fontColor: '#64748b' } }],
                  yAxes: [{ stacked: true, scaleLabel: { display: true, labelString: 'Outstanding Amount (₹)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { color: '#e2e8f0' } }]
              }
          }
      });
  }

  angular.element($window).on('resize', function() {
    if (salesChartInstance) salesChartInstance.resize();
    if (ageingChartInstance) ageingChartInstance.resize();
  });

  $scope.$on('$destroy', function() {
      angular.element($window).off('resize');
      if (salesChartInstance) { try{salesChartInstance.destroy();}catch(e){} }
      if (ageingChartInstance) { try{ageingChartInstance.destroy();}catch(e){} }
  });

  c.refresh = function() {
      c.loading = true;
      c.page = 0;
      var payload = { filters: angular.copy(c.filters) };
      if (c.data && c.data.filterOpts) payload.filterOpts = c.data.filterOpts;

      c.server.get(payload).then(function(r) {
          c.data = r.data;
          if (c.data.filterOpts && c.data.filterOpts.segments && c.data.filterOpts.segments.length === 1) {
              c.filters.segment = c.data.filterOpts.segments[0];
          }

          updateCounts();
          c.applyLocalFilters();
          c.buildTrendChart();
          c.renderCharts();
          $timeout(function(){ c.loading = false; }, 200);
      });
  };

  c.updatePagination = function() { c.page = 0; };
  c.getPageArray = function() {
      if (!c.filteredList) return [0];
      var totalPages = Math.ceil(c.filteredList.length / c.limit);
      if (totalPages === 0) return [0];
      var maxPage = totalPages - 1;
      var start = Math.max(0, c.page - 2);
      var end = Math.min(maxPage, c.page + 2);
      var arr = [];
      for (var i = start; i <= end; i++) { arr.push(i); }
      return arr;
  };

  c.fmtCurrency = function(value) {
      if (value === undefined || value === null || isNaN(value)) return '—';
      var abs = Math.abs(value);
      var sign = value < 0 ? '-' : '';
      if (abs === 0) return '₹0';
      if (abs >= 1e7) return sign + '₹' + (abs / 1e7).toFixed(1) + ' Cr';
      return sign + '₹' + (abs / 1e5).toFixed(1) + 'L';
  };
  c.fmtDash = function(val) { if (!val || isNaN(val) || val === 0) return '—'; return c.fmtCurrency(val); };
  c.fmtRatio = function(value) { if (value === undefined || value === null || isNaN(value)) return '—'; return Number(value).toFixed(2); };
  c.capPct = function(pct) { if (pct === undefined || pct === null || isNaN(pct)) return 0; return Math.max(0, Math.min(100, pct)); };

  c.selectCustomer = function(row) {
      if (!row || !row.sysId) return;
      $rootScope.clmPendingCustomerSysId = row.sysId;
      $rootScope.clmPendingCustomerCode = row.code;
      $rootScope.$broadcast('clm.customer.selected', { sysId: row.sysId, code: row.code });
      $rootScope.$broadcast('clm.switch.tab', 'customer360');
  };

  if (c.data && c.data.tableData) {
      updateCounts();
      c.applyLocalFilters();
      c.buildTrendChart();
      c.renderCharts();
  }
}

sp_widget.css:
/* Force Service Portal container to drop outer padding */
:host {
  display: block;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
}

.clm-portfolio-overview {
  font-family: "Helvetica Neue", Arial, sans-serif;
  color: #1f2933;
  padding: 16px 24px 24px 24px;
  margin: 0 16px;
  box-sizing: border-box;
}

/* ---- Filter Tracker & Clear All ---- */
.clm-filter-tracker {
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;
  padding: 10px 16px; background: #ffffff; border-bottom: 1px solid #e3e6eb;
}
.clm-tracker-chips { display: flex; flex-wrap: wrap; gap: 6px; flex: 1; }
.clm-tracker-chip {
  display: inline-flex; align-items: center; gap: 4px; background: #f8f9fa;
  border: 1px solid #cbd5e1; border-radius: 14px; padding: 4px 12px;
  font-size: 11px; font-weight: 600; color: #4a5568; cursor: pointer; transition: 0.15s;
}
.clm-tracker-chip i.fa-times { font-size: 10px; margin-left: 4px; color: #a0aec0; transition: color 0.15s; }
.clm-tracker-chip:hover { background: #edf2f7; border-color: #a0aec0; }
.clm-tracker-chip:hover i.fa-times { color: #e53e3e; }
.clm-clear-all-btn {
  background: #fff5f5; color: #e53e3e; border: 1px solid #feb2b2; border-radius: 14px;
  padding: 4px 14px; font-size: 11px; font-weight: 600; cursor: pointer;
  transition: 0.15s; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap;
}
.clm-clear-all-btn:hover { background: #e53e3e; color: #ffffff; border-color: #e53e3e; }

/* ---- Filters ---- */
.clm-filter-card {
  margin: 0 0 16px 0; background: #fff; border: 1px solid #e3e6eb;
  border-radius: 8px; padding: 14px 18px; overflow: visible; position: relative; z-index: 20;
}
.clm-filter-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.clm-filter-field { display: flex; align-items: center; gap: 6px; font-size: 13px; color: #1f2933; margin-bottom: 0; font-weight: 600; flex: 1; min-width: 160px; position: relative; }
.clm-filter-field select {
  width: 100%; height: 34px; font-size: 13px; border-radius: 4px;
  border: 1px solid #cbd5e1; background-color: #ffffff; padding: 0 10px; outline: none; cursor: pointer; transition: all 0.2s ease;
}
.clm-filter-field select:hover { border-color: #a0aec0; background-color: #f7fafc; }
.clm-filter-field select:focus { border-color: #1c4e9c; background-color: #ffffff; }

/* ---------- Multiselect Region & Depot ---------- */
.clm-multiselect-field { position: relative; }
.clm-multiselect-container { position: relative; width: 100%; min-width: 160px; }
.clm-multiselect-trigger {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; height: 34px; padding: 0 10px; font-size: 13px;
  border: 1px solid #cbd5e1; border-radius: 4px; background: #ffffff;
  cursor: pointer; box-sizing: border-box; transition: border-color 0.2s;
}
.clm-multiselect-trigger:hover { border-color: #a0aec0; }
.clm-multiselect-container.open .clm-multiselect-trigger { border-color: #1c4e9c; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.clm-multiselect-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #1f2933; flex: 1; }
.clm-multiselect-arrow { color: #a0aec0; font-size: 10px; margin-left: 6px; flex-shrink: 0; }
.clm-multiselect-dropdown {
  position: absolute; top: 34px; left: 0; right: 0; z-index: 60;
  background: #fff; border: 1px solid #1c4e9c; border-top: none;
  border-bottom-left-radius: 6px; border-bottom-right-radius: 6px;
  box-shadow: 0 6px 14px rgba(0,0,0,0.12); max-height: 280px; display: flex; flex-direction: column; overflow: hidden;
}
.clm-multiselect-actions { display: flex; justify-content: space-between; padding: 6px 10px; border-bottom: 1px solid #e3e6eb; background: #f8f9fa; }
.clm-multiselect-actions a { font-size: 11px; color: #1c4e9c; cursor: pointer; font-weight: 600; }
.clm-multiselect-actions a:hover { text-decoration: underline; }
.clm-multiselect-search { width: 100%; height: 32px; padding: 0 10px; border: none; border-bottom: 1px solid #e3e6eb; font-size: 12px; outline: none; box-sizing: border-box; }
.clm-multiselect-list { list-style: none; margin: 0; padding: 4px 0; overflow-y: auto; max-height: 180px; }
.clm-multiselect-list li { display: flex; align-items: center; gap: 8px; padding: 7px 12px; font-size: 13px; cursor: pointer; color: #1f2933; }
.clm-multiselect-list li:hover { background: #f0f4f9; }
.clm-multiselect-list li.selected { background: #ebf5ff; }
.clm-checkbox { width: 14px; height: 14px; border: 2px solid #cbd5e1; border-radius: 3px; display: inline-block; flex-shrink: 0; position: relative; }
.clm-checkbox.checked { background: #1c4e9c; border-color: #1c4e9c; }
.clm-checkbox.checked::after { content: ''; position: absolute; left: 3px; top: 1px; width: 4px; height: 7px; border: solid #fff; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.clm-dropdown-empty { color: #a0aec0 !important; cursor: default !important; font-style: italic; padding: 8px 12px; font-size: 13px; }

/* ---- KPIs ---- */
.clm-kpi-grid { display: grid; grid-template-columns: repeat(4, minmax(160px, 1fr)); gap: 14px; margin: 16px 0; }
.clm-kpi-card {
  position: relative; background: #fff; border: 1px solid #e3e6eb; border-left: 4px solid #c9ced6;
  border-radius: 6px; padding: 14px 16px; min-height: 100px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.02); transition: background-color 0.3s, box-shadow 0.3s;
}
.clm-kpi-card.border-blue   { border-left-color: #1c4e9c; }
.clm-kpi-card.border-orange { border-left-color: #dd6b20; }
.clm-kpi-card.border-green  { border-left-color: #38a169; }
.clm-kpi-card.border-teal   { border-left-color: #319795; }
.clm-kpi-card.border-red    { border-left-color: #e53e3e; }
.clm-kpi-card.border-purple { border-left-color: #7c3aed; }
.clm-kpi-code { font-size: 10px; font-weight: 700; color: #718096; margin-bottom: 6px; text-transform: uppercase; }
.clm-kpi-value { font-size: 24px; font-weight: 700; }
.clm-kpi-value.large { font-size: 28px; }
.clm-kpi-sub { font-size: 11px; color: #8a93a0; margin-top: 2px; }

.clm-kpi-info { position: absolute; top: 10px; right: 10px; color: #2b6cb0; font-size: 15px; transition: all 0.2s ease; cursor: pointer; z-index: 5; }
.clm-kpi-info:hover { color: #1c4e9c; transform: scale(1.15); }

.text-blue   { color: #2b6cb0; }
.text-orange { color: #dd6b20; }
.text-green  { color: #38a169; }
.text-teal   { color: #319795; }
.text-red    { color: #e53e3e; }
.text-purple { color: #7c3aed; }
.clm-progress { height: 4px; border-radius: 2px; background: #edf2f7; margin-top: 10px; }
.clm-progress-fill { height: 100%; border-radius: 2px; }
.bg-blue { background: #2b6cb0; }
.bg-teal { background: #319795; }

/* ---- Charts ---- */
.clm-chart-card { background: #fff; border: 1px solid #e3e6eb; border-radius: 8px; padding: 16px 20px; margin: 16px 0; overflow: hidden; position: relative; }
.clm-chart-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.clm-chart-title { font-size: 13px; font-weight: 700; color: #1f2933; }
.clm-chart-badge { font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 10px; }
.clm-badge-line    { background: #fff7e6; color: #b7791f; }
.clm-badge-combo   { background: #e6f0ff; color: #1c4e9c; }
.clm-badge-stacked { background: #f0e6ff; color: #6b21a8; }

.clm-trend-body { position: relative; height: 260px; padding-top: 10px; width: 100%; }
.clm-trend-svg { width: 100%; height: 260px; display: block; }
.clm-trend-area { fill: rgba(221, 107, 32, 0.1); }
.clm-trend-line { fill: none; stroke: #dd6b20; stroke-width: 2px; }
.clm-trend-dot { fill: #fff; stroke: #dd6b20; stroke-width: 2px; cursor: pointer; transition: r 0.2s; pointer-events: all; }
.clm-trend-dot:hover { r: 6; fill: #dd6b20; }
.clm-trend-dot.last { fill: #dd6b20; }
.clm-trend-grid line { stroke: #e2e8f0; stroke-dasharray: 4; stroke-width: 1px; }
.clm-trend-yaxis text, .clm-trend-xaxis text { font-size: 11px; fill: #718096; font-family: "Helvetica Neue", Arial, sans-serif; }
.clm-chart-empty { text-align: center; color: #a0aec0; padding: 20px; font-style: italic; }

.clm-charts-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin: 16px 0; }
@media (max-width: 768px) { .clm-charts-row { grid-template-columns: 1fr; } }
.clm-chart-half { margin: 0; overflow: hidden; position: relative; }

.clm-charts-row .clm-chart-wrapper {
  position: relative; height: 240px; width: 100%; padding: 10px 16px; box-sizing: border-box;
}
.clm-charts-row .clm-chart-wrapper canvas {
  width: 100% !important; height: 100% !important;
}

.clm-ageing-legend {
  display: flex; justify-content: center; gap: 20px; flex-wrap: wrap;
  margin-top: 14px; padding: 8px 0 4px 0;
}
.clm-legend-item { display: flex; align-items: center; gap: 6px; font-size: 12.5px; color: #334155; font-weight: 600; }
.clm-legend-color { width: 14px; height: 14px; border-radius: 3px; display: inline-block; }

/* ===================== TABLE SECTION ===================== */
.clm-table-container { margin: 16px 0; background: #fff; border: 1px solid #e3e6eb; border-radius: 8px; overflow: hidden; position: relative; transition: opacity 0.3s; }
.clm-chip-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 12px 16px; background: #fff; border-bottom: 1px solid #e3e6eb; }
.clm-chip {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px;
  font-size: 12px; font-weight: 600; color: #4a5568; background: #f8f9fa;
  border: 1px solid #e2e8f0; border-radius: 16px; cursor: pointer; transition: all 0.15s ease;
}
.clm-chip:hover { background: #eef2f7; border-color: #cbd5e1; }
.clm-chip.active { background: #1c4e9c; border-color: #1c4e9c; color: #ffffff; }
.clm-chip .clm-chip-count { background: rgba(0,0,0,0.08); color: inherit; border-radius: 10px; padding: 1px 7px; font-size: 11px; }
.clm-chip.active .clm-chip-count { background: rgba(255,255,255,0.25); }

.clm-table-toolbar-top { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; background: #fff; border-bottom: 1px solid #e3e6eb; }
.clm-search-box { position: relative; display: flex; align-items: center; flex: 1; max-width: 320px; }
.clm-search-box i { position: absolute; left: 12px; color: #a0aec0; font-size: 13px; }
.clm-search-box input {
  width: 100%; height: 34px; padding: 0 10px 0 32px; border: 1px solid #cbd5e1;
  border-radius: 6px; font-size: 13px; outline: none; transition: border 0.2s;
}
.clm-search-box input:focus { border-color: #1c4e9c; }
.clm-table-controls-right { display: flex; align-items: center; font-size: 12px; color: #4a5568; }
.clm-table-controls-right select { border: 1px solid #cbd5e1; border-radius: 4px; padding: 4px; height: 32px; outline: none; background: #fff; cursor: pointer; margin-left: 8px; }
.clm-record-count { font-weight: 600; }
.clm-badge-blue { background: #ebf8ff; color: #1c4e9c; padding: 4px 8px; border-radius: 12px; font-size: 11px; margin-left: 4px; }

/* Table Wrapper for Horizontal Scroll */
.clm-table-wrapper { 
  max-height: 450px; height: auto; overflow-y: auto; overflow-x: auto; -webkit-overflow-scrolling: touch; width: 100%; 
}
.clm-table { width: 100%; border-collapse: collapse; table-layout: auto; }

.clm-table thead th {
  position: sticky; top: 0; z-index: 10; text-align: left; padding: 10px 6px;
  background: #f8f9fa; color: #718096; font-weight: 600; text-transform: uppercase;
  font-size: 9px; border-bottom: 2px solid #cbd5e1; box-shadow: 0 2px 2px -1px rgba(0,0,0,0.1);
  white-space: normal !important; vertical-align: bottom; line-height: 1.2;
}

.clm-table td {
  padding: 8px 6px; border-bottom: 1px solid #edf2f7; color: #1f2933;
  font-size: 11px; vertical-align: middle; white-space: normal !important;
}

.clm-table tbody tr:hover { background-color: #f7fafc; }

.clm-table-footer { display: flex; justify-content: flex-end; align-items: center; padding: 10px 16px; background: #f8f9fa; border-top: 1px solid #e3e6eb; position: sticky; bottom: 0; z-index: 10; }
.clm-page-numbers { display: flex; gap: 4px; }
.clm-page-btn { background: #fff; border: 1px solid #cbd5e1; border-radius: 4px; height: 32px; min-width: 32px; cursor: pointer; color: #4a5568; font-weight: 600; display: flex; align-items: center; justify-content: center; }
.clm-page-btn:hover:not(:disabled) { background: #eef2f7; }
.clm-page-btn.active { background: #1c4e9c; color: #fff; border-color: #1c4e9c; }
.clm-page-btn:disabled { color: #a0aec0; background: #f8f9fa; cursor: not-allowed; border-color: #e2e8f0; }

.clm-nowrap { white-space: nowrap !important; }
.clm-code { color: #2b6cb0; font-weight: 600; cursor: pointer; }
.clm-sub-pan { display: block; font-size: 10px; color: #718096; margin-top: 2px; }

/* Status Badges */
.badge { display: inline-block; padding: 4px 8px; border-radius: 4px; font-size: 10px; font-weight: 600; }
.status-badge.st-submitted, .st-submitted { background: #ebf8ff; color: #1c4e9c; }
.status-badge.st-approved, .status-approved { background: #e3f4ea; color: #1f7a4d; }
.status-badge.st-pending, .status-submitted  { background: #fffdf0; color: #975a16; }
.status-badge.st-sendback, .st-sendback   { background: #f0e6ff; color: #6b21a8; }
.status-badge.st-rejected, .status-rejected { background: #fdeaea; color: #e53e3e; }

.seg-cement  { background: #ede9fe; color: #5b21b6; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }
.seg-bpd     { background: #fffdf0; color: #975a16; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }
.seg-rmc     { background: #f0f9ff; color: #1c4e9c; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }

.clm-strong { font-weight: 600; }
.clm-text-red { color: #e53e3e !important; font-weight: 600; }
.clm-text-orange { color: #dd6b20 !important; font-weight: 600; }
.clm-text-green { color: #38a169 !important; font-weight: 600; }
.clm-mini-progress { width: 32px; height: 4px; background: #edf2f7; border-radius: 2px; }
.clm-mini-fill { height: 100%; border-radius: 2px; background: currentColor; }

.clm-content-wrap { position: relative; min-height: 200px; }
.clm-content-wrap.clm-loading-active > *:not(.clm-loading-overlay) { opacity: 0.35; filter: blur(1px); pointer-events: none; transition: opacity 0.2s ease; }
.clm-loading-overlay { position: absolute; inset: 0; z-index: 60; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding-top: 60px; background: rgba(255,255,255,0.7); }
.clm-spinner { width: 34px; height: 34px; border: 3px solid #dbe3ee; border-top-color: #1c4e9c; border-radius: 50%; animation: clm-spin 0.7s linear infinite; }
.clm-loading-text { font-size: 13px; font-weight: 600; color: #4a5568; }
@keyframes clm-spin { to { transform: rotate(360deg); } }

sp_widget.script:
(function() {
    var TABLES = {
        tradeMaster:     'x_birl3_clm_clm_customer_master1',
        tradeReq:        'x_birl3_clm_clm_new_credit_request',
        tradeSnap:       'x_birl3_clm_clm_aging_snapshot',
        tradeRoleMap:    'x_birl3_clm_role_user_mapping',
        tradeSalesVal:   'x_birl3_clm_clm_cement_rmc_bpd_values',
        tradeSalesVol:   'x_birl3_clm_clm_sales_data',

        nonTradeMaster:  'x_birl3_clm_customer',
        nonTradeReq:     'x_birl3_clm_non_trade_clr',
        nonTradeSnap:    'x_birl3_clm_customer_outstanding',
        nonTradeRoleMap: 'x_birl3_clm_approval_matrix'
    };

    var inputFilters = (input && input.filters) ? input.filters : { businessType: 'all', period: 'latest' };
    var gdtToday = new GlideDateTime();
    var currentUserId = gs.getUserID();
    var businessType = inputFilters.businessType || 'all'; // 'all', 'T00', or 'N01'

    function normalizeArray(val) {
        if (typeof val === 'string') {
            try { val = JSON.parse(val); } catch (e) { val = val ? [val] : []; }
        }
        if (!Array.isArray(val)) { val = val ? [val] : []; }
        return val;
    }
    var regionList = normalizeArray(inputFilters.regions);
    var depotList = normalizeArray(inputFilters.depots);

    var MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    var monthNamesLower = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    function pad2(n) { return n < 10 ? '0' + n : '' + n; }

    // =========================================================
    // STEP 0: Check Dual Roles (Trade & Non-Trade)
    // =========================================================
    var hasTradeAccess = false, hasNonTradeAccess = false;
    var tradeRegions = [], nonTradeRegions = [];
    var tradeSegmentLabel = null, nonTradeSegmentLabel = null;

    // Check Trade Role
    var grTradeRole = new GlideRecord(TABLES.tradeRoleMap);
    grTradeRole.addQuery('u_user', currentUserId);
    grTradeRole.addQuery('u_role', 'IN', ['RHM', 'RH_CH_RMC']);
    grTradeRole.query();
    while (grTradeRole.next()) {
        hasTradeAccess = true;
        var rVal = grTradeRole.getValue('u_role');
        if (!tradeSegmentLabel) tradeSegmentLabel = (rVal === 'RHM') ? 'Cement' : 'RMC';
        var reg = grTradeRole.getValue('region_name');
        if (reg && tradeRegions.indexOf(reg) === -1) tradeRegions.push(reg);
    }

    // Check Non-Trade Role
    var grNTRole = new GlideRecord(TABLES.nonTradeRoleMap);
    grNTRole.addQuery('approver_user', currentUserId);
    grNTRole.query();
    while (grNTRole.next()) {
        var rName = (grNTRole.getValue('role_name') || '').toUpperCase();
        if (rName.indexOf('RHM') > -1 || rName.indexOf('RH') > -1) {
            hasNonTradeAccess = true;
            if (!nonTradeSegmentLabel) nonTradeSegmentLabel = grNTRole.getDisplayValue('segment') || grNTRole.getValue('segment');
            var reg2 = grNTRole.getValue('region');
            if (reg2 && nonTradeRegions.indexOf(reg2) === -1) nonTradeRegions.push(reg2);
        }
    }

    data.hasTradeAccess = hasTradeAccess;
    data.hasNonTradeAccess = hasNonTradeAccess;

    if (!hasTradeAccess && !hasNonTradeAccess) {
        data.accessDenied = true;
        data.accessMessage = 'You are not authorised to view this portfolio.';
        data.kpis = {}; data.tableData = []; data.trend = { points: [] }; data.salesTrend = { points: [] }; data.ageingTrend = { months: [] };
        return;
    }

    var activeSegmentLabel = tradeSegmentLabel || nonTradeSegmentLabel || 'Cement';

    // =========================================================
    // STEP 1: Unified Filter Options Generator
    // =========================================================
    var getDistinctPairs = function() {
        var map = {};

        // 1A. Trade Regions/Depots
        if ((businessType === 'all' || businessType === 'T00') && hasTradeAccess) {
            var gaT = new GlideAggregate(TABLES.tradeMaster);
            if (tradeRegions.length > 0) gaT.addQuery('region_name', 'IN', tradeRegions);
            if (regionList.length > 0) gaT.addQuery('region', 'IN', regionList);
            if (depotList.length > 0) gaT.addQuery('depot', 'IN', depotList);
            gaT.groupBy('region_name'); gaT.groupBy('region');
            gaT.query();
            while (gaT.next()) {
                var c = gaT.getValue('region'); if (!c) continue;
                var n = gaT.getValue('region_name') || c;
                map[c] = (n && c && n !== c) ? n + ' (' + c + ')' : n;
            }
        }

        // 1B. Non-Trade Regions/Depots (cg4)
        if ((businessType === 'all' || businessType === 'N01') && hasNonTradeAccess) {
            var gaNT = new GlideAggregate(TABLES.nonTradeMaster);
            if (nonTradeRegions.length > 0) gaNT.addQuery('cg4', 'IN', nonTradeRegions);
            if (regionList.length > 0) gaNT.addQuery('cg4', 'IN', regionList);
            if (depotList.length > 0) gaNT.addQuery('sales_office', 'IN', depotList);
            gaNT.groupBy('cg4');
            gaNT.query();
            while (gaNT.next()) {
                var c2 = gaNT.getValue('cg4'); if (!c2) continue;
                var n2 = gaNT.getDisplayValue('cg4') || c2;
                map[c2] = (n2 && c2 && n2 !== c2) ? n2 + ' (' + c2 + ')' : n2;
            }
        }

        var arr = [];
        for (var k in map) { arr.push({ value: k, label: map[k] }); }
        arr.sort(function(a, b) { return String(a.label).localeCompare(String(b.label)); });
        return arr;
    };

    data.filterOpts = {
        regions: getDistinctPairs(),
        depots: getDistinctPairs(),
        segments: [activeSegmentLabel],
        periods: [{ label: 'All Time (Latest)', value: 'latest' }]
    };

    // =========================================================
    // STEP 2: Fetch Scoped Master Customers & Requests
    // =========================================================
    var unifiedTableData = [];
    var now = new Date();
    var currentYear = now.getFullYear(), currentMonth = now.getMonth();

    // 2A. TRADE PIPELINE
    if ((businessType === 'all' || businessType === 'T00') && hasTradeAccess) {
        var grT = new GlideRecord(TABLES.tradeMaster);
        if (tradeRegions.length > 0) grT.addQuery('region_name', 'IN', tradeRegions);
        if (regionList.length > 0) grT.addQuery('region', 'IN', regionList);
        if (depotList.length > 0) grT.addQuery('depot', 'IN', depotList);
        grT.query();

        var tSysIds = [], tCustMap = {};
        while (grT.next()) {
            var sId = grT.getUniqueValue();
            tSysIds.push(sId);
            tCustMap[sId] = {
                sysId: sId, code: grT.getValue('customer_code_sap'), name: grT.getValue('customer_name'),
                pan: grT.getValue('pan'), segment: grT.getDisplayValue('segment') || activeSegmentLabel,
                region: grT.getValue('region_name') || grT.getValue('region'), depot: grT.getValue('depot_name') || grT.getValue('depot')
            };
        }

        if (tSysIds.length > 0) {
            // Fetch Trade Requests & Snapshots
            var tReqMap = {}, tSnapMap = {};
            var grTReq = new GlideRecord(TABLES.tradeReq);
            grTReq.addQuery('customer', 'IN', tSysIds);
            grTReq.orderByDesc('sys_created_on');
            grTReq.query();
            while (grTReq.next()) {
                var cId = grTReq.getValue('customer');
                if (!tReqMap[cId]) {
                    tReqMap[cId] = {
                        limit: parseFloat(grTReq.getValue('current_credit_limit')) || 0,
                        status: grTReq.getDisplayValue('state') || 'Active',
                        stateRaw: (grTReq.getValue('state') || '').toLowerCase(),
                        reviewDate: grTReq.getValue('next_review_date')
                    };
                }
            }

            var grTSnap = new GlideRecord(TABLES.tradeSnap);
            grTSnap.addQuery('customer', 'IN', tSysIds);
            grTSnap.orderByDesc('snapshot_month');
            grTSnap.query();
            while (grTSnap.next()) {
                var cId2 = grTSnap.getValue('customer');
                if (!tSnapMap[cId2]) {
                    tSnapMap[cId2] = {
                        outst: parseFloat(grTSnap.getValue('total_outstanding')) || 0,
                        b0_30: (parseFloat(grTSnap.getValue('bucket_0_30_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_22_30_days')) || 0),
                        b31_60: (parseFloat(grTSnap.getValue('bucket_31_45_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_46_60_days')) || 0),
                        b61_90: (parseFloat(grTSnap.getValue('bucket_61_75_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_76_90_days')) || 0),
                        bGt90: (parseFloat(grTSnap.getValue('bucket_91_120_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_121_180_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_181_365_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_366_730_days')) || 0) + (parseFloat(grTSnap.getValue('bucket_730_above')) || 0)
                    };
                }
            }

            for (var id in tCustMap) {
                var cObj = tCustMap[id];
                var req = tReqMap[id] || { limit: 0, status: 'No Request', stateRaw: '', reviewDate: '' };
                var snap = tSnapMap[id] || { outst: 0, b0_30: 0, b31_60: 0, b61_90: 0, bGt90: 0 };
                var rowOverdue = snap.b0_30 + snap.b31_60 + snap.b61_90 + snap.bGt90;
                var risk = snap.bGt90 > 0 ? 'High' : (snap.b61_90 > 0 ? 'Medium' : (rowOverdue > 0 ? 'Low' : 'No Overdue'));

                unifiedTableData.push({
                    businessType: 'Trade', sysId: cObj.sysId, code: cObj.code, name: cObj.name, pan: cObj.pan,
                    segment: cObj.segment, region: cObj.region, depot: cObj.depot, status: req.status,
                    stateRaw: req.stateRaw, outstanding: snap.outst, limit: req.limit, available: req.limit - snap.outst,
                    util: req.limit > 0 ? Math.round((snap.outst / req.limit) * 100) : 0, od90: snap.bGt90,
                    risk: risk, riskClass: risk === 'High' ? 'clm-text-red' : (risk === 'Medium' ? 'clm-text-orange' : 'clm-text-green'),
                    reviewIn: '--', osSalesRatio: 0, overdueTotal: rowOverdue
                });
            }
        }
    }

    // 2B. NON-TRADE PIPELINE
    if ((businessType === 'all' || businessType === 'N01') && hasNonTradeAccess) {
        var grNT = new GlideRecord(TABLES.nonTradeMaster);
        if (nonTradeRegions.length > 0) grNT.addQuery('cg4', 'IN', nonTradeRegions);
        if (regionList.length > 0) grNT.addQuery('cg4', 'IN', regionList);
        if (depotList.length > 0) grNT.addQuery('sales_office', 'IN', depotList);
        grNT.query();

        var ntSysIds = [], ntCustMap = {};
        while (grNT.next()) {
            var ntId = grNT.getUniqueValue();
            ntSysIds.push(ntId);
            ntCustMap[ntId] = {
                sysId: ntId, code: grNT.getValue('customer_code'), name: grNT.getValue('name'), pan: grNT.getValue('pan'),
                segment: activeSegmentLabel, region: grNT.getDisplayValue('cg4') || grNT.getValue('cg4'),
                depot: grNT.getDisplayValue('sales_office') || grNT.getValue('sales_office'),
                creditLimit: parseFloat(grNT.getValue('credit_limit')) || 0, reviewDate: grNT.getDisplayValue('next_review_date') || ''
            };
        }

        if (ntSysIds.length > 0) {
            var ntReqMap = {}, ntSnapMap = {};
            var grNTReq = new GlideRecord(TABLES.nonTradeReq);
            grNTReq.addQuery('customer_code', 'IN', ntSysIds);
            grNTReq.orderByDesc('sys_created_on');
            grNTReq.query();
            while (grNTReq.next()) {
                var ntCId = grNTReq.getValue('customer_code');
                if (!ntReqMap[ntCId]) {
                    ntReqMap[ntCId] = {
                        status: grNTReq.getDisplayValue('approval') || 'Active',
                        stateRaw: (grNTReq.getValue('approval') || '').toLowerCase()
                    };
                }
            }

            var grNTSnap = new GlideRecord(TABLES.nonTradeSnap);
            grNTSnap.addQuery('customer', 'IN', ntSysIds);
            grNTSnap.query();
            while (grNTSnap.next()) {
                var ntCId2 = grNTSnap.getValue('customer');
                if (!ntSnapMap[ntCId2]) {
                    ntSnapMap[ntCId2] = {
                        outst: parseFloat(grNTSnap.getValue('outstanding')) || 0,
                        b0_30: (parseFloat(grNTSnap.getValue('ageing0_3')) || 0) + (parseFloat(grNTSnap.getValue('ageing4_7')) || 0) + (parseFloat(grNTSnap.getValue('ageing8_21')) || 0) + (parseFloat(grNTSnap.getValue('ageing22_30')) || 0),
                        b31_60: (parseFloat(grNTSnap.getValue('ageing31_45')) || 0) + (parseFloat(grNTSnap.getValue('ageing46_60')) || 0),
                        b61_90: (parseFloat(grNTSnap.getValue('ageing61_75')) || 0) + (parseFloat(grNTSnap.getValue('ageing76_90')) || 0),
                        bGt90: parseFloat(grNTSnap.getValue('ageing_gt90')) || 0
                    };
                }
            }

            for (var idNT in ntCustMap) {
                var cObjNT = ntCustMap[idNT];
                var reqNT = ntReqMap[idNT] || { status: 'No Request', stateRaw: '' };
                var snapNT = ntSnapMap[idNT] || { outst: 0, b0_30: 0, b31_60: 0, b61_90: 0, bGt90: 0 };
                var rowOverdueNT = snapNT.b0_30 + snapNT.b31_60 + snapNT.b61_90 + snapNT.bGt90;
                var riskNT = snapNT.bGt90 > 0 ? 'High' : (snapNT.b61_90 > 0 ? 'Medium' : (rowOverdueNT > 0 ? 'Low' : 'No Overdue'));

                unifiedTableData.push({
                    businessType: 'Non-Trade', sysId: cObjNT.sysId, code: cObjNT.code, name: cObjNT.name, pan: cObjNT.pan,
                    segment: cObjNT.segment, region: cObjNT.region, depot: cObjNT.depot, status: reqNT.status,
                    stateRaw: reqNT.stateRaw, outstanding: snapNT.outst, limit: cObjNT.creditLimit, available: cObjNT.creditLimit - snapNT.outst,
                    util: cObjNT.creditLimit > 0 ? Math.round((snapNT.outst / cObjNT.creditLimit) * 100) : 0, od90: snapNT.bGt90,
                    risk: riskNT, riskClass: riskNT === 'High' ? 'clm-text-red' : (riskNT === 'Medium' ? 'clm-text-orange' : 'clm-text-green'),
                    reviewIn: '--', osSalesRatio: 0, overdueTotal: rowOverdueNT
                });
            }
        }
    }

    // =========================================================
    // STEP 3: Aggregated KPI Totals & Response Assembly
    // =========================================================
    var totalLimit = 0, totalOutst = 0, totalOverdue = 0, totalOd90 = 0;
    unifiedTableData.forEach(function(r) {
        totalLimit += r.limit;
        totalOutst += r.outstanding;
        totalOverdue += r.overdueTotal;
        totalOd90 += r.od90;
    });

    data.kpis = {
        customerCount: unifiedTableData.length,
        limit: totalLimit,
        outstanding: totalOutst,
        available: totalLimit - totalOutst,
        utilPct: totalLimit > 0 ? Math.round((totalOutst / totalLimit) * 100) : 0,
        overdueExposure: totalOverdue,
        od90: totalOd90,
        osSalesRatio: 0
    };
    data.tableData = unifiedTableData;

    // Build 6M Charts
    function build6M() {
        var out = [];
        for (var i = 5; i >= 0; i--) {
            var d = new Date(currentYear, currentMonth - i, 1);
            out.push({ label: MONTH_NAMES[d.getMonth()] + ' ' + String(d.getFullYear()).slice(-2), value: totalOutst, isFuture: false });
        }
        return out;
    }
    var chartPts = build6M();
    data.trend = { metric: 'outstanding', points: chartPts };
    data.salesTrend = { metric: 'sales', points: chartPts.map(function(p){ return { label: p.label, value: 0, volume: 0 }; }) };
    data.ageingTrend = { months: chartPts.map(function(p){ return { label: p.label, buckets: [{ label: '0-30 Days', value: 0 }, { label: '31-60 Days', value: 0 }, { label: '61-90 Days', value: 0 }, { label: '>90 Days', value: totalOd90 }] }; }) };

})();
